using System.Data; using System.Text.Json; using Forjix.Application.Abstractions.Purchases; using Forjix.Application.Abstractions.Sales; using Forjix.Application.Abstractions.Tenancy; using Forjix.Application.Common; using Forjix.Application.Features.Purchases; using Forjix.Domain.Entities.Audit; using Forjix.Domain.Entities.Inventory; using Forjix.Domain.Entities.Purchases; using Forjix.Domain.Enums; using Forjix.Infrastructure.Persistence.Tenant; using Microsoft.EntityFrameworkCore;
namespace Forjix.Infrastructure.Purchases;
internal sealed class PurchaseStoreFactory(ITenantDbContextFactory contexts):IPurchaseStoreFactory { public IPurchaseStore Create(ResolvedTenantDatabase tenant)=>new PurchaseStore(contexts.Create(tenant)); }
internal sealed class PurchaseStore(TenantDbContext db):IPurchaseStore {
 public async Task<(List<SupplierItem>,int)> GetSuppliersAsync(string? search,bool? active,int page,int size,CancellationToken ct){var q=db.Suppliers.AsNoTracking().AsQueryable();if(search is not null)q=q.Where(x=>x.Name.Contains(search)||(x.Document!=null&&x.Document.Contains(search)));if(active.HasValue)q=q.Where(x=>x.IsActive==active);var total=await q.CountAsync(ct);var items=await q.OrderBy(x=>x.Name).Skip((page-1)*size).Take(size).Select(x=>new SupplierItem(x.Id,x.Name,x.Document,x.Email,x.Phone,x.ContactName,x.Notes,x.IsActive,x.CreatedAt,x.UpdatedAt)).ToListAsync(ct);return(items,total);}
 public Task<Supplier?> FindSupplierAsync(Guid id,CancellationToken ct)=>db.Suppliers.SingleOrDefaultAsync(x=>x.Id==id,ct); public Task<bool> SupplierDocumentExistsAsync(string doc,Guid? except,CancellationToken ct)=>db.Suppliers.AnyAsync(x=>x.Document==doc&&(!except.HasValue||x.Id!=except),ct);
 public async Task<SupplierItem> SaveSupplierAsync(Supplier e,AuditLog audit,CancellationToken ct){if(db.Entry(e).State==EntityState.Detached)db.Suppliers.Add(e);db.AuditLogs.Add(audit);try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){throw new ResourceConflictException("Documento de fornecedor já cadastrado.");}return Map(e);}
 public async Task<(List<PurchaseListItem>,int)> GetPurchasesAsync(string? search,PurchaseStatus? status,int page,int size,CancellationToken ct){var q=db.Purchases.AsNoTracking().AsQueryable();if(search is not null)q=q.Where(x=>x.Number.Contains(search)||x.Supplier.Name.Contains(search));if(status.HasValue)q=q.Where(x=>x.Status==status);var total=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*size).Take(size).Select(x=>new PurchaseListItem(x.Id,x.Number,x.Supplier.Name,x.Status.ToString(),x.Total,x.Items.Count,x.CreatedAt,Convert.ToBase64String(x.RowVersion))).ToListAsync(ct);return(items,total);}
 public async Task<PurchaseView?> GetPurchaseAsync(Guid id,CancellationToken ct)=>MapNullable(await Query().SingleOrDefaultAsync(x=>x.Id==id,ct));
 public async Task<PurchaseView> CreatePurchaseAsync(Guid userId,CreatePurchaseRequest request,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var supplier=await db.Suppliers.SingleOrDefaultAsync(x=>x.Id==request.SupplierId,ct)??throw new ResourceNotFoundException("Fornecedor não encontrado.");if(!supplier.IsActive)throw new RequestValidationException("Fornecedor inativo.");if(request.Items.Select(x=>x.ProductId).Distinct().Count()!=request.Items.Count)throw new RequestValidationException("Não repita produtos na compra.");var ids=request.Items.Select(x=>x.ProductId).ToList();var products=await db.Products.Where(x=>ids.Contains(x.Id)).ToListAsync(ct);if(products.Count!=ids.Count||products.Any(x=>!x.IsActive))throw new RequestValidationException("Produto inválido ou inativo.");var date=DateOnly.FromDateTime(now.UtcDateTime);var seq=await db.PurchaseSequences.SingleOrDefaultAsync(x=>x.Date==date,ct);if(seq is null){seq=new PurchaseSequence{Date=date};db.PurchaseSequences.Add(seq);}seq.LastValue++;var p=new Purchase{Id=Guid.NewGuid(),Number=$"CP-{date:yyyyMMdd}-{seq.LastValue:00000}",SupplierId=supplier.Id,Notes=request.Notes?.Trim(),UserId=userId,CreatedAt=now,Total=request.Items.Sum(x=>x.Quantity*x.UnitCost)};foreach(var i in request.Items){var product=products.Single(x=>x.Id==i.ProductId);p.Items.Add(new PurchaseItem{Id=Guid.NewGuid(),ProductId=product.Id,ProductName=product.Name,Sku=product.Sku,Quantity=i.Quantity,UnitCost=i.UnitCost,Total=i.Quantity*i.UnitCost});}db.Purchases.Add(p);db.AuditLogs.Add(Audit(AuditAction.PurchaseCreated,p.Id,userId,ctx,now,new{p.Number,p.Total}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Map(await Query().SingleAsync(x=>x.Id==p.Id,ct));}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<PurchaseView> ReceiveAsync(Guid id,Guid userId,byte[] version,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);try{var p=await db.Purchases.Include(x=>x.Items).Include(x=>x.Supplier).Include(x=>x.User).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new ResourceNotFoundException("Compra não encontrada.");if(p.Status!=PurchaseStatus.Pending)throw new ResourceConflictException("Somente compras pendentes podem ser recebidas.");db.Entry(p).Property(x=>x.RowVersion).OriginalValue=version;var ids=p.Items.Select(x=>x.ProductId).ToList();var stocks=await db.Inventories.Where(x=>ids.Contains(x.ProductId)).ToListAsync(ct);if(stocks.Count!=ids.Count)throw new ResourceConflictException("Estoque de um produto não foi encontrado.");p.Receive(now);foreach(var i in p.Items){var stock=stocks.Single(x=>x.ProductId==i.ProductId);var c=stock.ApplyMovement(InventoryMovementType.Purchase,i.Quantity,true,now);db.InventoryMovements.Add(new InventoryMovement{InventoryId=stock.Id,ProductId=i.ProductId,Type=InventoryMovementType.Purchase,Quantity=i.Quantity,PreviousQuantity=c.PreviousQuantity,NewQuantity=c.NewQuantity,ReferenceType=nameof(Purchase),ReferenceId=p.Id.ToString(),UserId=userId,CreatedAt=now});}db.AuditLogs.Add(Audit(AuditAction.PurchaseReceived,p.Id,userId,ctx,now,new{p.Number,p.Total}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Map(p);}catch(DbUpdateConcurrencyException){await tx.RollbackAsync(ct);throw new ResourceConflictException("A compra ou o estoque foi alterado por outro usuário.");}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<PurchaseView> CancelAsync(Guid id,Guid userId,byte[] version,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);try{var p=await db.Purchases.Include(x=>x.Items).Include(x=>x.Supplier).Include(x=>x.User).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new ResourceNotFoundException("Compra não encontrada.");if(p.Status!=PurchaseStatus.Pending)throw new ResourceConflictException("Somente compras pendentes podem ser canceladas.");db.Entry(p).Property(x=>x.RowVersion).OriginalValue=version;p.Cancel(now);db.AuditLogs.Add(Audit(AuditAction.PurchaseCancelled,p.Id,userId,ctx,now,new{p.Number}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Map(p);}catch(DbUpdateConcurrencyException){await tx.RollbackAsync(ct);throw new ResourceConflictException("A compra foi alterada por outro usuário.");}catch{await tx.RollbackAsync(ct);throw;}}
 private IQueryable<Purchase> Query()=>db.Purchases.AsNoTracking().Include(x=>x.Supplier).Include(x=>x.User).Include(x=>x.Items);private static PurchaseView? MapNullable(Purchase? p)=>p is null?null:Map(p);private static PurchaseView Map(Purchase p)=>new(p.Id,p.Number,p.SupplierId,p.Supplier.Name,p.Status.ToString(),p.Total,p.Notes,p.UserId,p.User.Name,p.CreatedAt,p.ReceivedAt,p.CancelledAt,Convert.ToBase64String(p.RowVersion),p.Items.Select(i=>new PurchaseItemView(i.Id,i.ProductId,i.ProductName,i.Sku,i.Quantity,i.UnitCost,i.Total)).ToList());private static SupplierItem Map(Supplier x)=>new(x.Id,x.Name,x.Document,x.Email,x.Phone,x.ContactName,x.Notes,x.IsActive,x.CreatedAt,x.UpdatedAt);private static AuditLog Audit(AuditAction action,Guid id,Guid user,SalesAuditContext ctx,DateTimeOffset now,object data)=>new(){UserId=user,Action=action,EntityName=nameof(Purchase),EntityId=id.ToString(),AfterData=JsonSerializer.Serialize(data),CorrelationId=ctx.CorrelationId,IpAddress=ctx.IpAddress,OccurredAt=now};public ValueTask DisposeAsync()=>db.DisposeAsync(); }
